#include "modules/intrinsic_geometry_api.h"
#include <algorithm>
#include <cmath>
#include <cstring>
#include <iostream>
#include <vector>
namespace {
unsigned checks=0,failures=0;void verify(bool okay,const char* text){++checks;if(!okay){++failures;std::cerr<<"FAIL "<<text<<'\n';}}
int cancelled(void*){return 0;}int charge(void*,uint64_t,char*,uint64_t){return 0;}
struct Point {unsigned n;std::vector<double> metric,first,second,connection,connectionFirst,tensor,tensorFirst,frame,frameFirst;std::vector<int32_t> variance;penta_intrinsic_request_v1 request{};explicit Point(unsigned dimension):n(dimension),metric(n*n),first(n*n*n),second(n*n*n*n){for(unsigned j=0;j<n;++j)metric[j*n+j]=1;request.struct_size=sizeof(request);request.dimension=n;request.max_work=10000000;request.tolerance=1e-12;}void bind(){request.metric=metric.data();request.metric_first=first.data();request.metric_second=second.data();request.connection=connection.empty()?nullptr:connection.data();request.connection_first=connectionFirst.empty()?nullptr:connectionFirst.data();request.tensor=tensor.empty()?nullptr:tensor.data();request.tensor_first=tensorFirst.empty()?nullptr:tensorFirst.data();request.tensor_rank=variance.size();request.variance=variance.data();request.frame=frame.empty()?nullptr:frame.data();request.frame_first=frameFirst.empty()?nullptr:frameFirst.data();}};
struct Result {int status=0;std::vector<double> inverse,gamma,first,curvature,ricci,torsion,compatibility,covariant,frameConnection,frameBracket,frameMetric;penta_intrinsic_result_v1 report{};};
Result run(Point& point){point.bind();const auto n=point.n;Result r;r.inverse.resize(n*n);r.gamma.resize(n*n*n);r.first.resize(n*n*n*n);r.curvature.resize(n*n*n*n);r.ricci.resize(n*n);r.torsion.resize(n*n*n);r.compatibility.resize(n*n*n);r.covariant.resize(point.tensor.size()*n);r.frameConnection.resize(n*n*n);r.frameBracket.resize(n*n*n);r.frameMetric.resize(n*n);auto& out=r.report;out.struct_size=sizeof(out);out.tensor_capacity=r.covariant.size();out.inverse_metric=r.inverse.data();out.connection=r.gamma.data();out.connection_first=r.first.data();out.riemann=r.curvature.data();out.ricci=r.ricci.data();out.torsion=r.torsion.data();out.metric_covariant=r.compatibility.data();out.tensor_covariant=r.covariant.data();out.frame_connection=r.frameConnection.data();out.frame_bracket=r.frameBracket.data();out.frame_metric=r.frameMetric.data();penta_geometry_extra_host_v1 host{sizeof(host),PENTA_GEOMETRY_EXTRA_ABI_V1,nullptr,cancelled,charge,nullptr};char error[1024]{};r.status=penta_intrinsic_query_v1(PENTA_INTRINSIC_ABI_V1)->point(&host,&point.request,&out,error,sizeof(error));if(r.status)std::cerr<<"intrinsic status "<<r.status<<": "<<error<<'\n';return r;}
Point polar(){Point p(2);p.metric={1,0,0,4};p.first[3*2]=4;p.second[3*4]=2;return p;}
}
int main(){Point flat(3);flat.metric={1,0,0,0,4,0,0,0,9};auto r=run(flat);verify(!r.status&&r.report.scalar_curvature==0&&r.report.volume_density==6,"3D constant metric curvature and volume golden");verify(r.report.torsion_norm==0&&r.report.metric_covariant_norm==0,"Levi-Civita torsion and metric compatibility");Point p=polar();r=run(p);verify(!r.status&&std::abs(r.gamma[3]+2)<1e-12&&std::abs(r.gamma[5]-.5)<1e-12&&std::abs(r.report.scalar_curvature)<1e-12,"independent polar-coordinate connection and flat curvature");
Point sphere(2);const double angle=.8,R=2,s=std::sin(angle),c=std::cos(angle);sphere.metric={R*R,0,0,R*R*s*s};sphere.first[6]=2*R*R*s*c;sphere.second[12]=2*R*R*(c*c-s*s);r=run(sphere);verify(!r.status&&std::abs(r.report.scalar_curvature-.5)<1e-12&&std::abs(r.ricci[0]-1)<1e-12&&std::abs(r.ricci[3]-s*s)<1e-12,"round sphere Ricci/scalar curvature golden");Point product(4);product.metric[0]=4;product.metric[5]=4*s*s;product.first[5*4]=8*s*c;product.second[5*16]=8*(c*c-s*s);r=run(product);verify(!r.status&&std::abs(r.report.scalar_curvature-.5)<1e-12&&std::abs(r.ricci[10])<1e-12,"intrinsic4D sphere times flat-plane scalar curvature");
p=polar();p.tensor={2,0};p.tensorFirst={1,0,0,0};p.variance={1};r=run(p);verify(!r.status&&std::abs(r.covariant[0]-1)<1e-12&&std::abs(r.covariant[3]-1)<1e-12,"contravariant radial vector derivative golden");p.variance={-1};r=run(p);verify(!r.status&&std::abs(r.covariant[0]-1)<1e-12&&std::abs(r.covariant[3]-4)<1e-12,"covector radial gradient derivative golden");p=polar();p.tensor={1,0,0,.25};p.tensorFirst.assign(8,0);p.tensorFirst[6]=-.25;p.variance={1,1};r=run(p);verify(!r.status&&std::all_of(r.covariant.begin(),r.covariant.end(),[](double value){return std::abs(value)<1e-12;}),"general rank2 inverse metric is covariantly constant");
Point torsion(2);torsion.connection.assign(8,0);torsion.connectionFirst.assign(16,0);torsion.connection[1]=1;torsion.connection[6]=2;r=run(torsion);verify(!r.status&&r.torsion[1]==1&&r.torsion[2]==-1&&r.report.metric_covariant_norm>0&&!r.report.levi_civita,"general affine connection retains torsion/nonmetricity");verify(std::abs(r.curvature[1]-2)<1e-12&&std::abs(r.curvature[13]+2)<1e-12,"general connection curvature commutator golden");
p=polar();p.frame={1,0,0,.5};p.frameFirst.assign(8,0);p.frameFirst[6]=-.25;r=run(p);verify(!r.status&&std::abs(r.frameMetric[0]-1)<1e-12&&std::abs(r.frameMetric[3]-1)<1e-12,"moving orthonormal polar frame metric");verify(std::abs(r.frameBracket[5]+.5)<1e-12&&std::abs(r.frameBracket[6]-.5)<1e-12,"anholonomic polar frame Lie bracket golden");
const double a=.4,rad=2,cs=std::cos(a),sn=std::sin(a);double jac[]{cs,-rad*sn,sn,rad*cs},hessian[]{0,-sn,-sn,-rad*cs,0,cs,cs,-rad*sn},metric[]{1,0,0,4},gamma[]{0,0,0,-2,0,.5,.5,0},vector[]{1,0},covector[]{1,0},inverse[4]{},transformedMetric[4]{},transformedConnection[8]{},transformedVector[2]{},transformedCovector[2]{};penta_chart_transition_request_v1 q{sizeof(q),2,0,0,jac,hessian,metric,gamma,vector,covector,1e-12};penta_chart_transition_result_v1 out{sizeof(out),0,inverse,transformedMetric,transformedConnection,transformedVector,transformedCovector,0,0};char error[1024]{};const auto status=penta_intrinsic_query_v1(PENTA_INTRINSIC_ABI_V1)->transition(&q,&out,error,sizeof(error));verify(!status&&std::abs(transformedMetric[0]-1)<1e-12&&std::abs(transformedMetric[3]-1)<1e-12&&std::all_of(std::begin(transformedConnection),std::end(transformedConnection),[](double x){return std::abs(x)<1e-12;}),"polar-to-Cartesian transition transforms metric and connection including Hessian");verify(std::abs(transformedVector[0]-cs)<1e-12&&std::abs(transformedCovector[1]-sn)<1e-12,"contravariant/covariant chart transport golden");
Point invalid(2);invalid.metric[3]=-1;verify(run(invalid).status!=0,"indefinite metric rejected");invalid.metric[3]=1;invalid.request.max_work=1;verify(run(invalid).status==1,"intrinsic work precheck");std::cout<<checks<<" intrinsic geometry checks, "<<failures<<" failures\n";return failures?1:0;}
